  "description": "Ứng dụng hướng dẫn kỹ thuật hàn ống HDPE/PPR (Hàn mặt đầu & Hàn lồng) theo tiêu chuẩn ISO 21307, tích hợp trợ lý AI chuyên gia.",
  "requestFramePermissions": []
}

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export enum WeldingType {
  BUTT_FUSION = 'BUTT_FUSION',
  SOCKET_FUSION = 'SOCKET_FUSION',
  HOME = 'HOME'
}

export interface SocketFusionData {
  diameter: number;
  heatingTime: number; // seconds
  processingTime: number; // seconds
  coolingTime: number; // minutes
  insertionDepth: number; // mm
}

export interface ChatMessage {
  id: string;
  role: 'user' | 'model';
  text: string;
  timestamp: Date;
  isError?: boolean;
}

export interface ButtFusionParams {
  pipeDiameter: number; // mm
  sdr: number; // Standard Dimension Ratio
  dragPressure: number; // bar
  machineCylinderArea: number; // cm2 (Total effective piston area)
}

export interface ButtFusionResult {
  beadUpPressure: number;
  heatSoakPressure: number;
  heatSoakTime: number;
  changeOverTime: number;
  fusingPressure: number;
  coolingTime: number;
  beadHeight: number;
}

import { GoogleGenAI } from "@google/genai";

const SYSTEM_INSTRUCTION = `
Bạn là một chuyên gia hàng đầu về kỹ thuật hàn ống nhựa (HDPE, PPR) với hơn 20 năm kinh nghiệm. 
Kiến thức của bạn dựa trên tiêu chuẩn ISO 21307, DVS 2207 và các tiêu chuẩn quốc tế liên quan.

Nhiệm vụ của bạn:
1. Giải đáp thắc mắc về kỹ thuật hàn mặt đầu (Butt Fusion) và hàn lồng (Socket Fusion).
2. Tư vấn giải quyết sự cố (Troubleshooting) khi mối hàn bị lỗi (lệch, bọt khí, không ngấu, v.v.).
3. Nhắc nhở về an toàn lao động và chuẩn bị bề mặt ống.
4. Cung cấp thông số tham khảo nếu người dùng hỏi, nhưng luôn nhắc họ kiểm tra thông số máy cụ thể.

Phong cách trả lời:
- Chuyên nghiệp, ngắn gọn, dễ hiểu cho kỹ sư và thợ thi công.
- Sử dụng tiếng Việt chuyên ngành (ví dụ: gia nhiệt, áp suất kéo, thời gian chuyển đổi, chiều cao gờ).
- Định dạng câu trả lời sử dụng Markdown để dễ đọc (dùng bullet points, bold text).

Nếu người dùng hỏi về vấn đề không liên quan đến hàn ống hoặc xây dựng, hãy lịch sự từ chối và quay lại chủ đề hàn ống.
`;

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

export const sendMessageToGemini = async (message: string, history: { role: string; parts: [{ text: string }] }[]) => {
  try {
    const chat = ai.chats.create({
      model: 'gemini-3-flash-preview',
      config: {
        systemInstruction: SYSTEM_INSTRUCTION,
        temperature: 0.7,
      },
      history: history,
    });

    const result = await chat.sendMessage({ message });
    return result.text;
  } catch (error) {
    console.error("Gemini API Error:", error);
    throw error;
  }
};

import React, { useState, useEffect } from 'react';
import { Calculator, Settings, Info, ArrowRight, PlayCircle } from 'lucide-react';
import { ButtFusionParams, ButtFusionResult } from '../types';

const ButtFusion: React.FC = () => {
  // Default Params
  const [params, setParams] = useState<ButtFusionParams>({
    pipeDiameter: 200,
    sdr: 11,
    dragPressure: 10,
    machineCylinderArea: 10, // Hypothetical default, usually found on machine plate
  });

  const [result, setResult] = useState<ButtFusionResult | null>(null);

  // Constants based on ISO 21307 - Single Low Pressure (Standard)
  // Interfacial Pressure usually 0.15 MPa (= 1.5 bar)
  const INTERFACIAL_PRESSURE = 1.5; // bar

  const calculateParams = () => {
    // 1. Calculate Pipe Geometry
    const outerDiameter = params.pipeDiameter;
    const thickness = outerDiameter / params.sdr;
    const innerDiameter = outerDiameter - 2 * thickness;

    // Annular Area (Surface area to be welded) in cm2
    // A = pi * (OD^2 - ID^2) / 4
    // Convert mm to cm for area calculation: Divide by 100
    const areaWelding = (Math.PI * (Math.pow(outerDiameter/10, 2) - Math.pow(innerDiameter/10, 2))) / 4;

    // 2. Calculate Theoretical Pressure (P_bead)
    // P_theory (bar) = (Welding Area * Interfacial Pressure) / Cylinder Area
    const pressureTheory = (areaWelding * INTERFACIAL_PRESSURE) / params.machineCylinderArea;

    // 3. Total Gauge Pressure
    // P_gauge = P_drag + P_theory
    const gaugePressure = params.dragPressure + pressureTheory;

    // 4. Times (Approximations based on ISO 21307 for HDPE)
    // Heat Soak Time: 10s + (0.5 * Wall Thickness) ?? Actually usually T * 10 or similar
    // ISO 21307 Single Low Pressure: 
    // Bead build-up: until bead size reached
    // Heat soak: ~ 10-12s per mm of thickness (simplified rule of thumb for this demo)
    const heatSoakTime = Math.ceil(thickness * 12); 

    // Change over time: Max time allowed
    let changeOver = 0;
    if (outerDiameter <= 200) changeOver = 10; // approximate
    else changeOver = 20;

    // Cooling time under pressure
    // Rule of thumb: ~ 1 min per mm thickness + base
    const coolingTime = Math.ceil(thickness * 1.5); 

    // Bead Height (mm)
    const beadHeight = 0.5 + 0.1 * thickness; // Rough approximation

    setResult({
      beadUpPressure: Number(gaugePressure.toFixed(1)), // Same as fusion pressure for bead up
      heatSoakPressure: params.dragPressure, // Drop to drag pressure (approx 0 + drag)
      heatSoakTime: heatSoakTime,
      changeOverTime: changeOver,
      fusingPressure: Number(gaugePressure.toFixed(1)),
      coolingTime: coolingTime,
      beadHeight: Number(beadHeight.toFixed(1))
    });
  };

  useEffect(() => {
    calculateParams();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [params]);

  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const { name, value } = e.target;
    setParams(prev => ({ ...prev, [name]: Number(value) }));
  };

  return (
    <div className="max-w-6xl mx-auto p-4 space-y-8 animate-fade-in">
       <div className="text-center space-y-2">
        <h2 className="text-3xl font-bold text-slate-800">Hàn Mặt Đầu (Butt Fusion)</h2>
        <p className="text-slate-600">Tiêu chuẩn ISO 21307 - Phương pháp áp suất thấp đơn (Single Low Pressure)</p>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">

        {/* INPUT PANEL */}
        <div className="lg:col-span-1 bg-white rounded-xl shadow-lg border border-slate-200 p-6 space-y-6">
          <div className="flex items-center gap-2 mb-4 border-b pb-4">
            <Settings className="text-blue-600" />
            <h3 className="text-xl font-bold text-slate-800">Thông số đầu vào</h3>
          </div>

          <div className="space-y-4">
            <div>
              <label className="block text-sm font-medium text-slate-700 mb-1">Đường kính ống (OD) - mm</label>
              <input 
                type="number" name="pipeDiameter" value={params.pipeDiameter} onChange={handleInputChange}
                className="w-full p-2 border border-slate-300 rounded focus:ring-2 focus:ring-blue-500 focus:outline-none"
              />
            </div>
            <div>
              <label className="block text-sm font-medium text-slate-700 mb-1">Chỉ số SDR (Standard Dimension Ratio)</label>
              <div className="flex gap-2">
                {[11, 13.6, 17, 21].map(val => (
                  <button 
                    key={val}
                    onClick={() => setParams(p => ({...p, sdr: val}))}
                    className={`px-3 py-1 text-sm rounded border ${params.sdr === val ? 'bg-blue-600 text-white border-blue-600' : 'bg-white text-slate-600 border-slate-300'}`}
                  >
                    {val}
                  </button>
                ))}
              </div>
            </div>
            <div>
              <label className="block text-sm font-medium text-slate-700 mb-1">
                Áp suất kéo (P<sub>drag</sub>) - bar
                <span className="block text-xs text-slate-400 font-normal">Đọc trên đồng hồ khi máy chạy không tải</span>
              </label>
              <input 
                type="number" name="dragPressure" value={params.dragPressure} onChange={handleInputChange}
                className="w-full p-2 border border-slate-300 rounded focus:ring-2 focus:ring-blue-500 focus:outline-none"
              />
            </div>
            <div>
              <label className="block text-sm font-medium text-slate-700 mb-1">
                Diện tích xy-lanh thủy lực - cm²
                <span className="block text-xs text-slate-400 font-normal">Xem tem máy hàn (Total Piston Area)</span>
              </label>
              <input 
                type="number" name="machineCylinderArea" value={params.machineCylinderArea} onChange={handleInputChange}
                className="w-full p-2 border border-slate-300 rounded focus:ring-2 focus:ring-blue-500 focus:outline-none"
              />
            </div>

            <button 
              onClick={calculateParams}
              className="w-full bg-blue-600 text-white py-2 rounded hover:bg-blue-700 transition flex justify-center items-center gap-2"
            >
              <Calculator size={18} /> Tính toán thông số
            </button>
          </div>
        </div>

        {/* RESULTS PANEL */}
        <div className="lg:col-span-2 space-y-6">
          {result && (
            <div className="bg-slate-900 text-white rounded-xl shadow-xl overflow-hidden">
               <div className="bg-slate-800 p-4 flex justify-between items-center">
                  <h3 className="font-bold text-lg flex items-center gap-2">
                    <Info className="text-blue-400" /> Bảng Thông Số Kỹ Thuật
                  </h3>
                  <span className="text-xs bg-blue-600 px-2 py-1 rounded">Tham khảo ISO 21307</span>
               </div>

               <div className="p-6 grid grid-cols-2 md:grid-cols-3 gap-8">
                  <div className="space-y-1">
                    <p className="text-slate-400 text-sm">Áp suất hàn (P<sub>gauge</sub>)</p>
                    <p className="text-4xl font-bold text-blue-400">{result.fusingPressure} <span className="text-lg text-slate-500">bar</span></p>
                    <p className="text-xs text-slate-500">P<sub>welding</sub> + P<sub>drag</sub></p>
                  </div>
                  <div className="space-y-1">
                    <p className="text-slate-400 text-sm">Thời gian gia nhiệt</p>
                    <p className="text-4xl font-bold text-amber-400">{result.heatSoakTime} <span className="text-lg text-slate-500">s</span></p>
                    <p className="text-xs text-slate-500">Tại áp suất {params.dragPressure} bar</p>
                  </div>
                  <div className="space-y-1">
                    <p className="text-slate-400 text-sm">Thời gian làm nguội</p>
                    <p className="text-4xl font-bold text-emerald-400">{result.coolingTime} <span className="text-lg text-slate-500">min</span></p>
                    <p className="text-xs text-slate-500">Giữ nguyên áp suất</p>
                  </div>
                  <div className="space-y-1">
                    <p className="text-slate-400 text-sm">Thời gian chuyển đổi (Max)</p>
                    <p className="text-2xl font-semibold text-white">{result.changeOverTime} <span className="text-sm text-slate-500">s</span></p>
                  </div>
                  <div className="space-y-1">
                    <p className="text-slate-400 text-sm">Chiều cao gờ (Bead)</p>
                    <p className="text-2xl font-semibold text-white">{result.beadHeight} <span className="text-sm text-slate-500">mm</span></p>
                  </div>
               </div>
            </div>
          )}

          {/* PROCESS VISUALIZATION */}
          <div className="bg-white rounded-xl shadow border border-slate-200 p-6">
            <h3 className="font-bold text-lg text-slate-800 mb-4">Quy trình hàn 5 giai đoạn</h3>
            <div className="space-y-6 relative border-l-2 border-slate-200 ml-3 pl-8 pb-2">
              {[
                { title: '1. Chuẩn bị & Tạo gờ (Bead-up)', desc: `Tăng áp suất lên ${result?.beadUpPressure} bar cho đến khi gờ tiếp xúc đạt ${result?.beadHeight}mm quanh chu vi.`, icon: 'params' },
                { title: '2. Gia nhiệt (Heat Soak)', desc: `Giảm áp suất về P_drag (${params.dragPressure} bar). Duy trì trong ${result?.heatSoakTime} giây để nhiệt ngấm sâu.`, icon: 'clock' },
                { title: '3. Chuyển đổi (Change-over)', desc: `Tách đĩa nhiệt ra nhanh nhất có thể (tối đa ${result?.changeOverTime}s). Kiểm tra bề mặt nóng chảy.`, icon: 'action' },
                { title: '4. Ép mối hàn (Joining)', desc: `Tăng áp suất đều đặn lên ${result?.fusingPressure} bar.`, icon: 'pressure' },
                { title: '5. Làm nguội (Cooling)', desc: `Duy trì áp suất ${result?.fusingPressure} bar trong ${result?.coolingTime} phút. Tuyệt đối không tưới nước.`, icon: 'cool' },
              ].map((step, idx) => (
                <div key={idx} className="relative">
                  <span className="absolute -left-[41px] top-0 bg-blue-100 text-blue-600 w-8 h-8 rounded-full flex items-center justify-center font-bold border-2 border-white shadow-sm ring-1 ring-slate-200">
                    {idx + 1}
                  </span>
                  <h4 className="font-bold text-slate-800 text-md">{step.title}</h4>
                  <p className="text-slate-600 text-sm mt-1">{step.desc}</p>
                </div>
              ))}
            </div>
          </div>
        </div>

      </div>
    </div>
  );
};

export default ButtFusion;

import React, { useState, useRef, useEffect } from 'react';
import { Send, Bot, User, X, MessageSquare, Loader2 } from 'lucide-react';
import { ChatMessage } from '../types';
import { sendMessageToGemini } from '../services/geminiService';
import ReactMarkdown from 'react-markdown';

const AIChat: React.FC = () => {
  const [isOpen, setIsOpen] = useState(false);
  const [messages, setMessages] = useState<ChatMessage[]>([
    {
      id: 'welcome',
      role: 'model',
      text: 'Xin chào! Tôi là trợ lý ảo chuyên về kỹ thuật hàn ống ISO 21307. Bạn cần hỗ trợ về hàn mặt đầu hay hàn lồng?',
      timestamp: new Date()
    }
  ]);
  const [inputText, setInputText] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const messagesEndRef = useRef<HTMLDivElement>(null);

  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  };

  useEffect(() => {
    scrollToBottom();
  }, [messages, isOpen]);

  const handleSend = async () => {
    if (!inputText.trim() || isLoading) return;

    const userMsg: ChatMessage = {
      id: Date.now().toString(),
      role: 'user',
      text: inputText,
      timestamp: new Date()
    };

    setMessages(prev => [...prev, userMsg]);
    setInputText('');
    setIsLoading(true);

    try {
      // Prepare history for API
      const history = messages.map(m => ({
        role: m.role,
        parts: [{ text: m.text }]
      }));

      const responseText = await sendMessageToGemini(userMsg.text, history);

      const botMsg: ChatMessage = {
        id: (Date.now() + 1).toString(),
        role: 'model',
        text: responseText || "Xin lỗi, tôi không thể trả lời lúc này.",
        timestamp: new Date()
      };
      setMessages(prev => [...prev, botMsg]);
    } catch (error) {
      const errorMsg: ChatMessage = {
        id: (Date.now() + 1).toString(),
        role: 'model',
        text: "Đã xảy ra lỗi kết nối. Vui lòng kiểm tra API Key hoặc thử lại sau.",
        timestamp: new Date(),
        isError: true
      };
      setMessages(prev => [...prev, errorMsg]);
    } finally {
      setIsLoading(false);
    }
  };

  const handleKeyPress = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault();
      handleSend();
    }
  };

  return (
    <>
      {/* Floating Button */}
      {!isOpen && (
        <button
          onClick={() => setIsOpen(true)}
          className="fixed bottom-6 right-6 bg-blue-600 hover:bg-blue-700 text-white p-4 rounded-full shadow-2xl transition-all transform hover:scale-110 z-50 flex items-center gap-2"
        >
          <Bot size={28} />
          <span className="font-semibold hidden md:inline">Hỏi Chuyên Gia AI</span>
        </button>
      )}

      {/* Chat Window */}
      {isOpen && (
        <div className="fixed bottom-4 right-4 w-[90vw] md:w-[400px] h-[500px] bg-white rounded-2xl shadow-2xl border border-slate-200 z-50 flex flex-col overflow-hidden animate-in slide-in-from-bottom-10 fade-in duration-300">

          {/* Header */}
          <div className="bg-gradient-to-r from-blue-700 to-blue-600 p-4 flex justify-between items-center text-white">
            <div className="flex items-center gap-2">
              <div className="bg-white/20 p-1.5 rounded-lg">
                <Bot size={20} />
              </div>
              <div>
                <h3 className="font-bold text-sm">Trợ Lý Kỹ Thuật</h3>
                <p className="text-xs text-blue-100 flex items-center gap-1">
                  <span className="w-2 h-2 bg-green-400 rounded-full inline-block animate-pulse"></span>
                  Online
                </p>
              </div>
            </div>
            <button onClick={() => setIsOpen(false)} className="hover:bg-white/20 p-1 rounded transition">
              <X size={20} />
            </button>
          </div>

          {/* Messages Area */}
          <div className="flex-1 overflow-y-auto p-4 space-y-4 bg-slate-50 scrollbar-hide">
            {messages.map((msg) => (
              <div
                key={msg.id}
                className={`flex ${msg.role === 'user' ? 'justify-end' : 'justify-start'}`}
              >
                <div
                  className={`max-w-[85%] rounded-2xl px-4 py-3 text-sm shadow-sm ${
                    msg.role === 'user'
                      ? 'bg-blue-600 text-white rounded-br-none'
                      : 'bg-white text-slate-800 border border-slate-100 rounded-bl-none'
                  } ${msg.isError ? 'bg-red-50 border-red-200 text-red-600' : ''}`}
                >
                  {msg.role === 'model' ? (
                     <ReactMarkdown 
                        className="prose prose-sm max-w-none prose-blue dark:prose-invert"
                        components={{
                          ul: ({node, ...props}) => <ul className="list-disc pl-4 my-1" {...props} />,
                          li: ({node, ...props}) => <li className="my-0.5" {...props} />,
                          strong: ({node, ...props}) => <span className="font-bold text-blue-700" {...props} />
                        }}
                     >
                        {msg.text}
                     </ReactMarkdown>
                  ) : (
                    msg.text
                  )}
                  <span className={`text-[10px] block mt-1 opacity-70 ${msg.role === 'user' ? 'text-blue-100' : 'text-slate-400'}`}>
                    {msg.timestamp.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
                  </span>
                </div>
              </div>
            ))}
            {isLoading && (
              <div className="flex justify-start">
                <div className="bg-white border border-slate-100 rounded-2xl rounded-bl-none px-4 py-3 shadow-sm flex items-center gap-2">
                  <Loader2 size={16} className="animate-spin text-blue-600" />
                  <span className="text-xs text-slate-500">Đang suy nghĩ...</span>
                </div>
              </div>
            )}
            <div ref={messagesEndRef} />
          </div>

          {/* Input Area */}
          <div className="p-3 bg-white border-t border-slate-100">
            <div className="flex gap-2 relative">
              <input
                type="text"
                value={inputText}
                onChange={(e) => setInputText(e.target.value)}
                onKeyDown={handleKeyPress}
                placeholder="Nhập câu hỏi kỹ thuật..."
                className="w-full pl-4 pr-12 py-3 bg-slate-100 rounded-full text-sm focus:outline-none focus:ring-2 focus:ring-blue-500 transition-all placeholder:text-slate-400"
              />
              <button
                onClick={handleSend}
                disabled={!inputText.trim() || isLoading}
                className="absolute right-1 top-1 bottom-1 bg-blue-600 hover:bg-blue-700 disabled:bg-slate-300 text-white rounded-full w-10 flex items-center justify-center transition-colors"
              >
                <Send size={18} />
              </button>
            </div>
          </div>

        </div>
      )}
    </>
  );
};

export default AIChat;

import React from 'react';
