      { step: 4, timeLabel: `${result.heatSoakTime}s`, pressure: P_drag, phase: '2. Gia Nhiệt' }, // End Heat Soak
      { step: 4.1, timeLabel: 'Change', pressure: 0, phase: '3. Chuyển Đổi' }, // Drop for Changeover
      { step: 5, timeLabel: `${result.changeOverTime}s`, pressure: 0, phase: '3. Chuyển Đổi' }, // End Changeover
      { step: 5.2, timeLabel: 'Join', pressure: P_weld, phase: '4. Ép' }, // Ramp up
      { step: 8, timeLabel: `${result.coolingTime}m`, pressure: P_weld, phase: '5. Làm Nguội' }, // End Cooling
